<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  X, Y: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">Integer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
