<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Bitmap.Clear(clWhite32); </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">// Clear internally calls Changed</span></span>
